// 빌드 산출물 회귀 가드 — `pnpm build` 산출물이 4 플랫폼 디렉토리에 모두 존재하고
// 핵심 토큰 / placeholder / auto-generated 헤더가 보존되는지.
//
// CI 의 drift 가드 (`git diff --exit-code`) 가 산출물 != source 를 잡지만, 그 가드는
// "현재 트리의 산출물 상태"만 본다. 이 테스트는 "산출물 자체가 의도대로 생긴 모양인가"
// 를 검증 — esbuild 옵션 변경 / placeholder 처리 변경 등 byte-level 회귀 차단.

import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();

const ARTIFACTS = {
  chrome: 'chrome-extension/content-scripts/main.js',
  safariExt: 'safari-extension/QuietLounge/Shared (Extension)/Resources/content-scripts/main.js',
  iosAfter: 'safari-extension/QuietLounge/iOS (App)/Resources/webview-scripts/after.js',
  androidAfter: 'android-app/app/src/main/assets/webview-scripts/after.js',
};

// PR #5 / #6 에서 추가된 before.js / api-interceptor.js 산출물.
const BEFORE_ARTIFACTS = {
  iosBefore: 'safari-extension/QuietLounge/iOS (App)/Resources/webview-scripts/before.js',
  androidBefore: 'android-app/app/src/main/assets/webview-scripts/before.js',
};
const API_INTERCEPTOR_ARTIFACTS = {
  chromeApi: 'chrome-extension/content-scripts/api-interceptor.js',
  safariExtApi:
    'safari-extension/QuietLounge/Shared (Extension)/Resources/content-scripts/api-interceptor.js',
};

function read(rel) {
  return fs.readFileSync(path.resolve(ROOT, rel), 'utf8');
}

describe('빌드 산출물 — 4 플랫폼 모두 존재 + auto-generated 헤더', () => {
  for (const [name, rel] of Object.entries(ARTIFACTS)) {
    it(`${name} (${rel}) — 파일 존재 + 헤더`, () => {
      const text = read(rel);
      expect(text.length).toBeGreaterThan(1000);
      expect(text).toContain('auto-generated by scripts/build.mjs');
      expect(text).toContain('Source: shared/web/');
    });
  }
});

describe('Tier 1 핵심 토큰 보존 — 4 플랫폼 산출물', () => {
  // 모든 플랫폼 공통 토큰 — selectors, cleanbot 관련.
  const COMMON_TOKENS = ['isCleanbotFiltered', '클린봇', '감지'];
  // storage 키는 Chrome / Safari ext 만 사용 (iOS/Android 는 placeholder 로 직접 주입).
  const STORAGE_TOKEN = 'quiet_lounge_data';

  for (const [name, rel] of Object.entries(ARTIFACTS)) {
    it(`${name} — 공통 토큰 모두 포함`, () => {
      const text = read(rel);
      for (const tok of COMMON_TOKENS) {
        expect(text).toContain(tok);
      }
    });
  }

  it('Chrome / Safari ext 만 storage 키 (quiet_lounge_data) 보유', () => {
    expect(read(ARTIFACTS.chrome)).toContain(STORAGE_TOKEN);
    expect(read(ARTIFACTS.safariExt)).toContain(STORAGE_TOKEN);
    // iOS / Android 는 native bridge 가 직접 주입 → 키 없음.
    expect(read(ARTIFACTS.iosAfter)).not.toContain(STORAGE_TOKEN);
    expect(read(ARTIFACTS.androidAfter)).not.toContain(STORAGE_TOKEN);
  });
});

describe('iOS / Android 산출물 — placeholder 보존', () => {
  // native bridge 가 빌드 후 텍스트 치환으로 주입할 두 placeholder 가 살아있어야 한다.
  // esbuild 가 minify / define 으로 우연히 치환하면 런타임에 차단 데이터가 안 들어가 차단 동작 silent 사망.
  for (const name of ['iosAfter', 'androidAfter']) {
    it(`${name} — __QL_BLOCK_DATA_PLACEHOLDER__ 보존`, () => {
      const text = read(ARTIFACTS[name]);
      expect(text).toContain('__QL_BLOCK_DATA_PLACEHOLDER__');
      expect(text).toContain('__QL_FILTER_MODE_PLACEHOLDER__');
    });
  }

  it('Chrome / Safari ext 산출물에는 placeholder 없음 (storage API 사용)', () => {
    expect(read(ARTIFACTS.chrome)).not.toContain('__QL_BLOCK_DATA_PLACEHOLDER__');
    expect(read(ARTIFACTS.safariExt)).not.toContain('__QL_BLOCK_DATA_PLACEHOLDER__');
  });

  describe('placeholder 치환 — 따옴표 종류와 무관 (Bug #1 회귀 가드)', () => {
    // 과거 회귀: Swift `WebViewScripts` 가 `'__QL_FILTER_MODE_PLACEHOLDER__'` (single quote 포함)
    // 형태로 검색했는데 esbuild 가 string literal 을 double quote 로 출력해 매치 실패 →
    // window.__QL_FILTER_MODE 가 placeholder 문자열 그대로 남고 'blur' 비교가 영원히 false →
    // 흐림 모드가 hide 처럼 동작하는 silent 회귀.
    //
    // Native bridge (Swift / Kotlin) 측은 bare token 으로만 치환하고 따옴표는 산출물에 그대로
    // 두는 패턴 (`__QL_FILTER_MODE_PLACEHOLDER__` → `blur` 만 치환, `"..."` 유지) 을 사용해야
    // 따옴표 종류 무관하게 작동한다.

    function bareTokenReplace(text, blockDataValue, filterModeValue) {
      // Swift / Kotlin 측 로직의 mirror (단순 문자열 치환).
      return text
        .replaceAll('__QL_BLOCK_DATA_PLACEHOLDER__', blockDataValue)
        .replaceAll('__QL_FILTER_MODE_PLACEHOLDER__', filterModeValue);
    }

    for (const name of ['iosAfter', 'androidAfter']) {
      it(`${name} — bare token 치환 후 __QL_FILTER_MODE 가 정확히 'blur' 또는 'hide' 로 평가됨`, () => {
        const text = read(ARTIFACTS[name]);
        const subbed = bareTokenReplace(text, '{"version":2,"blockedUsers":{},"nicknameOnlyBlocks":[]}', 'blur');
        // 치환 후 placeholder 흔적이 0 이어야 함.
        expect(subbed).not.toContain('__QL_BLOCK_DATA_PLACEHOLDER__');
        expect(subbed).not.toContain('__QL_FILTER_MODE_PLACEHOLDER__');
        // window.__QL_FILTER_MODE = "blur" / 'blur' / `blur` 형태로 정확히 들어가는지 (esbuild 가
        // 어떤 따옴표를 쓰든 OK).
        expect(subbed).toMatch(/window\.__QL_FILTER_MODE\s*=\s*['"`]blur['"`]/);
        // window.__QL_BLOCK_DATA = {...} 가 bare object literal 로 평가됨.
        expect(subbed).toMatch(/window\.__QL_BLOCK_DATA\s*=\s*\{"version":2/);
      });

      it(`${name} — 'hide' 모드도 동일하게 치환`, () => {
        const text = read(ARTIFACTS[name]);
        const subbed = bareTokenReplace(text, '{}', 'hide');
        expect(subbed).toMatch(/window\.__QL_FILTER_MODE\s*=\s*['"`]hide['"`]/);
      });
    }
  });
});

describe('before.js 산출물 — iOS / Android 둘 다 존재 + 핵심 토큰', () => {
  for (const [name, rel] of Object.entries(BEFORE_ARTIFACTS)) {
    it(`${name} (${rel}) — 파일 존재 + auto-generated 헤더`, () => {
      const text = read(rel);
      expect(text.length).toBeGreaterThan(500);
      expect(text).toContain('auto-generated by scripts/build.mjs');
    });
    it(`${name} — fetch monkey-patch + __QL 초기화 보유`, () => {
      const text = read(rel);
      expect(text).toContain('__QL_BEFORE_INSTALLED');
      expect(text).toContain('api.lounge.naver.com');
    });
  }
  it('iOS before.js — webkit.messageHandlers.qlBridge 호출 패턴', () => {
    const text = read(BEFORE_ARTIFACTS.iosBefore);
    expect(text).toContain('qlBridge');
  });
  it('Android before.js — window.QuietLounge.postMessage 패턴', () => {
    const text = read(BEFORE_ARTIFACTS.androidBefore);
    expect(text).toContain('QuietLounge');
  });
});

describe('api-interceptor.js 산출물 — Chrome / Safari ext 둘 다 동일 source', () => {
  for (const [name, rel] of Object.entries(API_INTERCEPTOR_ARTIFACTS)) {
    it(`${name} (${rel}) — 파일 존재 + 헤더`, () => {
      const text = read(rel);
      expect(text.length).toBeGreaterThan(500);
      expect(text).toContain('auto-generated by scripts/build.mjs');
    });
    it(`${name} — page→content message 변환 + REQUEST_DATA 응답 패턴`, () => {
      const text = read(rel);
      expect(text).toContain('QUIET_LOUNGE_API_DATA');
      expect(text).toContain('QUIET_LOUNGE_REQUEST_DATA');
      expect(text).toContain('api.lounge.naver.com');
    });
  }

  it('Chrome / Safari ext api-interceptor 산출물은 *내용 동일* (단일 entry, 두 outfile)', () => {
    const a = read(API_INTERCEPTOR_ARTIFACTS.chromeApi);
    const b = read(API_INTERCEPTOR_ARTIFACTS.safariExtApi);
    expect(a).toBe(b);
  });
});

describe('산출물 함수명 보존 — keepNames 옵션 회귀 가드', () => {
  // 4 플랫폼 entry 의 inline 코드는 cleanbot-skip.test.js 의 source-level guard 가 의존하는
  // `function isCleanbotFiltered(`, `\w+\.closest(` 같은 패턴을 보유. esbuild minify=true 로
  // 회귀하면 식별자가 변형되어 source guard 가 깨진다.
  for (const [name, rel] of Object.entries(ARTIFACTS)) {
    it(`${name} — function isCleanbotFiltered( 패턴 보존`, () => {
      const text = read(rel);
      expect(text).toMatch(/function\s+isCleanbotFiltered\s*\(/);
    });
  }
});
